import unittest

from report import report_time


class ReportTimeTests(unittest.TestCase):
    def test_converts_utc_and_z_suffix_to_report_timezone(self):
        self.assertEqual(
            report_time("2024-01-15T00:30:00Z"),
            "2024-01-15 08:30",
        )

    def test_handles_negative_offset_crossing_report_date(self):
        self.assertEqual(
            report_time("2024-01-15T23:30:00-05:00"),
            "2024-01-16 12:30",
        )

    def test_preserves_report_date_for_positive_offset(self):
        self.assertEqual(
            report_time("2024-01-15T23:59:59+08:00"),
            "2024-01-15 23:59",
        )

    def test_rejects_timestamp_without_timezone(self):
        with self.assertRaisesRegex(ValueError, "timezone"):
            report_time("2024-01-15T12:00:00")


if __name__ == "__main__":
    unittest.main()
